components.example:
import { Accordion } from "@leeward/react";

export function FeesFaq() {
  return <Accordion items={[{ value: "fees", title: "What does a transfer cost?", content: "Free between Leeward accounts." }]} />;
}

import { Alert, Button } from "@leeward/react";

export function LimitWarning() {
  return (
    <Alert tone="warning" title="You are close to your daily limit" actions={<Button size="sm">Raise limit</Button>}>
      ₺1.500 left today. Limits reset at midnight.
    </Alert>
  );
}

import { Avatar } from "@leeward/react";

export function Recipient() {
  return <Avatar name="Deniz Yılmaz" />;
}

import { Badge } from "@leeward/react";

export function PendingBadge() {
  return <Badge tone="warning">Pending</Badge>;
}

import { Button } from "@leeward/react";

export function SendButton() {
  return (
    <Button iconStart="send" onClick={() => console.log("send")}>
      Send money
    </Button>
  );
}

import { Card, Heading, Text } from "@leeward/react";

export function SavingsGoal() {
  return (
    <Card as="section" variant="elevated" padding="lg" aria-labelledby="goal">
      <Heading level={2} size="h4" id="goal">Holiday fund</Heading>
      <Text tone="secondary">You saved ₺4.500 of ₺10.000.</Text>
    </Card>
  );
}

import { Checkbox } from "@leeward/react";

export function SaveRecipient() {
  return <Checkbox label="Save this person as a recipient" onCheckedChange={(checked) => console.log(checked)} />;
}

import { CheckboxGroup } from "@leeward/react";

export function StatementAccounts() {
  return (
    <CheckboxGroup
      label="Include these accounts"
      selectAllLabel="All accounts"
      defaultValue={["everyday"]}
      options={[
        { value: "everyday", label: "Everyday" },
        { value: "savings", label: "Rainy day savings" },
        { value: "business", label: "Business", disabled: true, hint: "Statements for business accounts come from Leeward Business" },
      ]}
    />
  );
}

import { useState } from "react";
import { Chip } from "@leeward/react";

export function MoneyInFilter() {
  const [selected, setSelected] = useState(false);
  return <Chip selected={selected} onSelectedChange={setSelected}>Money in</Chip>;
}

import { Button, Dialog, DialogClose } from "@leeward/react";

export function FreezeCard() {
  return (
    <Dialog
      title="Freeze your card?"
      description="Card payments stop until you unfreeze it."
      trigger={<Button variant="secondary">Freeze card</Button>}
      actions={
        <>
          <DialogClose asChild><Button variant="ghost">Keep it active</Button></DialogClose>
          <DialogClose asChild><Button>Freeze card</Button></DialogClose>
        </>
      }
    />
  );
}

import { Divider } from "@leeward/react";

export function OrDivider() {
  return <Divider label="or" />;
}

import { DropdownMenu, IconButton } from "@leeward/react";

export function AccountMenu() {
  return (
    <DropdownMenu
      trigger={<IconButton icon="more-vertical" label="More actions" />}
      actions={[
        { label: "Copy IBAN", icon: "copy", onSelect: () => {} },
        { label: "Close account", icon: "trash", onSelect: () => {}, destructive: true },
      ]}
    />
  );
}

import { Button, EmptyState } from "@leeward/react";

export function NoPayments() {
  return <EmptyState icon="wallet-money" title="No payments yet" description="Your payments show up here." action={<Button iconStart="send">Send money</Button>} />;
}

import { Heading } from "@leeward/react";

export function SectionTitle() {
  return <Heading level={2} size="h3">Recent activity</Heading>;
}

import { Icon } from "@leeward/react";

export function Secured() {
  return <Icon name="lock" label="Secured" />;
}

import { IconButton } from "@leeward/react";

export function CloseButton({ onClose }: { onClose: () => void }) {
  return <IconButton icon="close" label="Close" onClick={onClose} />;
}

import { Link } from "@leeward/react";

export function FeesLink() {
  return <Link href="/fees" variant="standalone">See all fees</Link>;
}

import { Icon, List, ListItem } from "@leeward/react";

export function SettingsList() {
  return (
    <List>
      <ListItem title="Security" description="Passcode, Face ID" leading={<Icon name="shield" />} href="/security" chevron />
      <ListItem title="Notifications" leading={<Icon name="bell" />} href="/notifications" chevron />
    </List>
  );
}

import { ProgressBar } from "@leeward/react";

export function HolidayFund() {
  return <ProgressBar label="Holiday fund" value={4500} max={10000} valueText="₺4.500 of ₺10.000" />;
}

import { RadioGroup } from "@leeward/react";

export function WhenToSend() {
  return (
    <RadioGroup
      label="When should it arrive?"
      defaultValue="now"
      options={[
        { value: "now", label: "Now", description: "Free, arrives in seconds" },
        { value: "date", label: "On a date", description: "Choose a day in the next 12 months" },
      ]}
    />
  );
}

import { SegmentedControl } from "@leeward/react";

export function PeriodPicker() {
  return (
    <SegmentedControl
      label="Period"
      defaultValue="month"
      options={[
        { value: "week", label: "Week" },
        { value: "month", label: "Month" },
        { value: "year", label: "Year" },
      ]}
    />
  );
}

import { Select } from "@leeward/react";

export function PayFrom() {
  return (
    <Select
      label="Pay from"
      options={[
        { value: "everyday", label: "Everyday account" },
        { value: "savings", label: "Savings" },
      ]}
      onValueChange={(value) => console.log(value)}
    />
  );
}

import { Button, Checkbox, Sheet, SheetClose } from "@leeward/react";

export function Filters() {
  return (
    <Sheet title="Filter transactions" trigger={<Button variant="outline" iconStart="filter">Filter</Button>} footer={<SheetClose asChild><Button>Show results</Button></SheetClose>}>
      <Checkbox label="Pending only" />
    </Sheet>
  );
}

import { Skeleton } from "@leeward/react";

export function LoadingList() {
  return (
    <div role="status" aria-busy="true" aria-label="Loading transactions">
      <Skeleton shape="circle" />
      <Skeleton lines={2} />
    </div>
  );
}

import { Spinner } from "@leeward/react";

export function Loading() {
  return <Spinner label="Loading your accounts" />;
}

import { Stepper } from "@leeward/react";

export function TransferProgress() {
  return <Stepper steps={["Recipient", "Amount", "Review", "Confirm"]} current={1} label="Transfer progress" />;
}

import { useState } from "react";
import { Switch } from "@leeward/react";

export function OnlinePayments() {
  const [on, setOn] = useState(true);
  return <Switch label="Online card payments" checked={on} onCheckedChange={setOn} />;
}

import { Tabs, Text } from "@leeward/react";

export function AccountViews() {
  return (
    <Tabs
      label="Account views"
      items={[
        { value: "activity", label: "Activity", content: <Text>Last 30 days</Text> },
        { value: "details", label: "Details", content: <Text>IBAN and branch</Text> },
      ]}
    />
  );
}

import { Text } from "@leeward/react";

export function TransferNote() {
  return <Text variant="body-sm" tone="secondary">Transfers to other banks take up to one working day.</Text>;
}

import { TextField } from "@leeward/react";

export function IbanField({ error }: { error?: string }) {
  return <TextField label="IBAN" hint="26 characters, starts with TR" autoComplete="off" {...(error ? { error } : {})} />;
}

import { Textarea } from "@leeward/react";

export function PaymentNote() {
  return <Textarea label="Payment note" hint="The recipient sees this" optional maxLength={140} showCount />;
}

import { Button, useToast } from "@leeward/react";

export function SendWithToast() {
  const toast = useToast();
  return <Button onClick={() => toast.show({ title: "Money sent", description: "Deniz gets ₺250,00 in a few seconds.", tone: "success" })}>Send</Button>;
}

import { IconButton, Tooltip } from "@leeward/react";

export function FeeInfo() {
  return (
    <Tooltip content="The fee is the same for every amount.">
      <IconButton icon="info" label="About the fee" />
    </Tooltip>
  );
}

import { AccountCard } from "@leeward/react";

export function Everyday() {
  return (
    <AccountCard
      name="Everyday"
      type="Current account"
      iban="TR33 0006 1005 1978 6457 8413 26"
      balance={24580.35}
      currency="TRY"
      locale="tr-TR"
      actions={[{ label: "Send", icon: "send", onClick: () => {} }]}
    />
  );
}

import { AmountDisplay } from "@leeward/react";

export function Incoming() {
  return <AmountDisplay value={1250} currency="TRY" locale="tr-TR" direction="incoming" />;
}

import { AmountInput } from "@leeward/react";

export function TransferAmount() {
  return <AmountInput label="Amount" currency="TRY" locale="tr-TR" max={24580.35} hint="Available: ₺24.580,35" onValueChange={(value) => console.log(value)} />;
}

import { BalanceHeader } from "@leeward/react";

export function HomeBalance() {
  return <BalanceHeader label="Available balance" balance={24580.35} currency="TRY" locale="tr-TR" meta="Updated just now" />;
}

import { OTPInput } from "@leeward/react";

export function VerifyTransfer() {
  return <OTPInput label="Verification code" hint="We sent a code to •••• 4821" onComplete={(code) => console.log(code)} />;
}

import { PaymentCard } from "@leeward/react";

export function DebitCard() {
  return (
    <div style={{ maxWidth: "340px" }}>
      <PaymentCard name="Everyday debit" last4="4821" expiry="08/28" holder="Ece Kaya" type="Debit" />
    </div>
  );
}

import { QuickActions } from "@leeward/react";

export function HomeShortcuts() {
  return (
    <QuickActions
      label="Quick actions"
      actions={[
        { label: "Send", icon: "send", onClick: () => {} },
        { label: "Request", icon: "hand-money", onClick: () => {} },
      ]}
    />
  );
}

import { List, RecipientRow } from "@leeward/react";

export function Recipients() {
  return (
    <List aria-label="Saved recipients">
      <RecipientRow name="Deniz Yılmaz" bank="Leeward" iban="TR33 0006 1005 1978 6457 8413 26" favorite onClick={() => {}} />
      <RecipientRow name="Ece Kaya" bank="Ziraat Bankası" iban="TR12 0001 0012 3456 7890 1234 56" onClick={() => {}} />
    </List>
  );
}

import { SavingsGoal } from "@leeward/react";

export function HolidayFund() {
  return (
    <SavingsGoal
      name="Holiday fund"
      saved={18500}
      target={30000}
      currency="TRY"
      locale="tr-TR"
      targetDate={new Date("2027-06-01")}
      onAddMoney={() => {}}
    />
  );
}

import { SpendingBreakdown } from "@leeward/react";

export function NovemberSpending() {
  return (
    <SpendingBreakdown
      title="Spending in November"
      currency="TRY"
      locale="tr-TR"
      categories={[
        { name: "Groceries", amount: 4200, icon: "cart" },
        { name: "Bills", amount: 3100, icon: "bill" },
        { name: "Eating out", amount: 1850, icon: "restaurant" },
        { name: "Transport", amount: 960, icon: "transport" },
      ]}
    />
  );
}

import { AmountDisplay, SummaryList } from "@leeward/react";

export function TransferReview() {
  return (
    <SummaryList
      items={[
        { label: "Recipient", value: "Deniz Yılmaz" },
        { label: "Amount", value: <AmountDisplay value={250} currency="TRY" locale="tr-TR" /> },
        { label: "Fee", value: <AmountDisplay value={0} currency="TRY" locale="tr-TR" />, hint: "Free for Leeward accounts" },
        { label: "Arrives", value: "In a few seconds" },
      ]}
      total={{ label: "Total", value: <AmountDisplay value={250} currency="TRY" locale="tr-TR" /> }}
    />
  );
}

import { List, TransactionRow } from "@leeward/react";

export function Activity() {
  return (
    <List>
      <TransactionRow merchant="Coffee Lab" category="Eating out" date={new Date("2026-11-12")} amount={85} direction="outgoing" currency="TRY" locale="tr-TR" icon="coffee" />
    </List>
  );
}
